    "content": "&nbsp; &nbsp; 从昨天晚上到今天白天家里边就剩了我们两个。有人会觉得多难得的二人世界呀！可是事实上我们没有一刻不在聊孩子。 &nbsp; &nbsp; 某人说数年以后这就成了我们俩的常态。因他的工作性质不常在家，所以两个孩子上学之后我一人在家的时间比较多。这次他难得在家休息几天，如果不是因为我要天天上班，我们俩一定会驾车远行。因为我们两个都是属于那种喜欢旅行的人，只是受到家庭的牵绊而无法出行。所以我们就把外出散步定在了晚上，我们两个会徒步走很远很远的路，这一刻我们是享受这一点自由时间的。有时候我们连手机…"
