    "description": "新华社北京10月21日电 题：以“双碳”为牵引加快全面绿色转型——生态环境部介绍我国应对气候变化工作成效 新华社记者高敬、何晓 “十五五”时期是我国实现碳达峰的决胜期。生态环境部副部长李高在国务院新闻办公室21日举行的新闻发布会上表示，要以碳达峰碳中和为牵引，实施《国家应对气候变化“十五五”规划》，推动重点领域绿色低碳发展，全面实施碳排放总量和强度双控制度，加快推进全国碳市场建设，深入推进气候适应型社会建设，加快推动经济社会发展全面绿色…",
    "content": "新华社北京10月21日电 题：以“双碳”为牵引加快全面绿色转型——生态环境部介绍我国应对气候变化工作成效 新华社记者高敬、何晓 “十五五”时期是我国实现碳达峰的决胜期。生态环境部副部长李高在国务院新闻办公室21日举行的新闻发布会上表示，要以碳达峰碳中和为牵引，实施《国家应对气候变化“十五五”规划》，推动重点领域绿色低碳发展，全面实施碳排放总量和强度双控制度，加快推进全国碳市场建设，深入推进气候适应型社会建设，加快推动经济社会发展全面绿色转型。 推动应对气候变化工作取得显著成效 李高说，近年来，我国采取优化能源和产业…"
