    "author": "",
    "description": "36氪获悉，中共中央办公厅、国务院办公厅《关于推动科技创新和产业创新深度融合的意见》对外发布。其中指出，以关键核心技术突破提升产业链自主可控水平。推动集成电路、工业母机、高端仪器、先进材料、生物制造等重点领域关键核心技术攻关取得决定性突破。深入实施产业基础再造和重大技术装备攻关等工程，聚焦重点领域薄弱环节，强化基础零部件及基础元器件攻关，突破关键基础软件，攻克关键基础材料，加强先进基础工艺和产业技术基础研发。",
