    "content": "新华社亚的斯亚贝巴10月21日电（记者刘方强）非洲疾病预防控制中心主任卡塞亚20日在社交媒体上表示，全球应加强团结，共同应对，阻止本轮埃博拉疫情进一步蔓延。 尼日利亚成为本轮疫情中第四个发现埃博拉确诊病例的非洲国家。尼日利亚卫生和社会福利部20日发布公告说，经实验室检测，一名从乌干达乘机抵达尼首都阿布贾的女子确诊感染埃博拉病毒，目前已接受隔离治疗。尼政府已启动防止病毒传播的公共卫生措施。 目前，疫情已影响刚果（金）所在的中非、乌干达和肯尼亚所在的东非和尼日利亚所在的西非。 “我们不能允许这次疫情蔓延到更多国家，也不…"
