    "description": "中新网西宁10月21日电 (李隽)“1月至8月，全省社会消费品零售总额实现666.13亿元(人民币，下同)，剔除汽车因素消费品同比增长3.1%，高于全国平均水平；网络零售额124.90亿元，同比增长32.8%。”21日，青海省商务厅党组成员、副厅长李宁在青海省开局起步“十五五”主题系列新闻发布会商务发展专场上说。",
