    "content": "快科技10月21日消息，据第一财经报道，针对比亚迪L3级别车辆何时落地，比亚迪集团高级副总裁、汽车新技术研究院院长杨冬生在世界智能网联汽车大会上表示， L3级别有条件自动驾驶有希望在2028年落地，更高级别自动驾驶通过迭代，有望再过1-2年落地。 比亚迪目前在智驾领域的主力系统是“天神之眼”，2026年1月已升级至5.0版本，强化了无图城市NOA等高阶能力。比亚迪智驾团队每七天迭代一次模型，2024年新增训练里程7200万公里。 L3级自动驾驶的核心特征是在特定条件下从“人机共驾”转向“机器驾驶”，驾驶员在系统请求…"
