    "content": "新华社北京10月21日电（记者邵艺博）中共中央政治局委员、外交部长王毅将于10月23日出席2026全球治理论坛（雄安）开幕式并作主旨发言。外交部发言人毛宁21日在例行记者会上介绍了有关情况和中方对此次论坛的期待。 毛宁表示，本次论坛以“重建信心与合作：百年变局与改革完善全球治理”为主题，邀请各国人士相聚雄安，共商改革完善全球治理大计。 毛宁说，王毅外长将在论坛开幕式提出进一步落实全球治理倡议、推动构建更加公正合理全球治理体系的务实举措，还将会见与会外国嘉宾代表。 “我们相信中外嘉宾将以本次论坛为契机，助力国际社会携…"
