    "description": "记者从国务院新闻办公室今天（21日）举行的“开局起步‘十五五’”系列主题新闻发布会上了解到，今年中央安全生产考核巡查二、三季度明查暗访共发现重大事故隐患950项。从严查处了一批煤矿隐蔽工作面开采、货车“百吨王”运输、瞒报事故、检验检测机构弄虚作假等违法行为，明查暗访实效性显著提升。",
