    "content": "当下，最顶配的活法是什么？搜索一下，满屏都在劝你回归身体基建：练薄肌、喝大水、睡大觉…… 这些活法大多简单粗暴但管用。 唯独有一个没那么简单， 需要多角度的精细配合才能达成，那就是“练薄肌”。 近期爆火的练薄肌 ｜ 微博@在在丫丫 野生的“薄肌”，线条干净、紧实不夸张 “薄肌”是个刚从社交平台长出来的野生词，翻遍运动医学教材，你也找不到它的定义。 刷刷打着“薄肌”标签的图片，大致能看出来，它是介于“纸片人”和“绿巨人”之间的一种状态， 清瘦紧实但不干瘪、能看出肌肉线条但不夸张、有着肩宽腰细的倒三角形。 为了得到这样…"
