    "title": "我国持续加强非二氧化碳温室气体控制",
    "link": "http://www.news.cn/20261021/5aa911a5312d44bea90dbacf5d963a5e/c.html",
    "pub_date": "2026-10-21 17:07:23",
    "author": "",
    "description": "新华社北京10月21日电（记者高敬、何晓）生态环境部副部长李高21日表示，近年来，我国控制非二氧化碳温室气体工作持续加强，以更好推动应对气候变化工作。 “目前，通过国际多边机制来进行管控的温室气体有7种，除了大家比较熟悉的二氧化碳以外，还包括甲烷、氧化亚氮、氢氟碳化物、全氟化碳、六氟化硫、三氟化氮等6种温室气体。”李高在国务院新闻办公室当天举行的新闻发布会上说。 他介绍，这些气体的排放量比二氧化碳少，但单位排放的温室效应是二氧化碳的几十…",
    "content": "新华社北京10月21日电（记者高敬、何晓）生态环境部副部长李高21日表示，近年来，我国控制非二氧化碳温室气体工作持续加强，以更好推动应对气候变化工作。 “目前，通过国际多边机制来进行管控的温室气体有7种，除了大家比较熟悉的二氧化碳以外，还包括甲烷、氧化亚氮、氢氟碳化物、全氟化碳、六氟化硫、三氟化氮等6种温室气体。”李高在国务院新闻办公室当天举行的新闻发布会上说。 他介绍，这些气体的排放量比二氧化碳少，但单位排放的温室效应是二氧化碳的几十倍甚至更多。同时，有的气体如甲烷，有较高的回收利用价值，还有一些气体可以通过成熟…"
