    "title": "快速识别诈骗电话 遇到这四种号码请勿接勿回",
    "link": "http://www.news.cn/20261021/fde0708134254663bae33f5f999e554a/c.html",
    "pub_date": "2026-10-21 16:57:17",
    "author": "",
    "description": "接到可疑诈骗电话，通话时间越长，被骗风险越高，接听者还可能被标记为“优质目标”受到反复骚扰。 警方提示，接到“400”开头外呼电话、“00”开头陌生国际长途、“95”开头8位号码，以及“1069”开头带链接短信，务必做到不接听、不点击、不回复。一旦遇到可疑情况，请及时拨打110报警。 记者：李亚光 素材来源：国家反诈中心 新华社音视频部制作",
    "content": "接到可疑诈骗电话，通话时间越长，被骗风险越高，接听者还可能被标记为“优质目标”受到反复骚扰。 警方提示，接到“400”开头外呼电话、“00”开头陌生国际长途、“95”开头8位号码，以及“1069”开头带链接短信，务必做到不接听、不点击、不回复。一旦遇到可疑情况，请及时拨打110报警。 记者：李亚光 素材来源：国家反诈中心 新华社音视频部制作"
