    "pub_date": "2026-10-21 16:53:52",
    "author": "",
    "description": "中新网南昌10月21日电 (熊锦阳)10月21日，《关于支持城市更新行动强化规划和土地保障的若干举措》新闻发布会在江西省南昌市举行。会上就江西省自然资源厅会同江西省住房和城乡建设厅共同研究制定的《关于支持城市更新行动强化规划和土地保障的若干举措》(以下简称《若干举措》)相关情况进行了介绍。",
