    "content": "前三季度，规模以上工业增加值同比增长5.3%，工业对经济增长的贡献率保持在35%左右……在20日举行的国新办新闻发布会上，工业和信息化部有关负责人详解2026年前三季度工业和信息化发展情况。 工业和信息化部总工程师王卫明表示，今年以来，工业和信息化系统统筹稳增长、强创新、促转型、优环境，积极应对风险挑战，工业和信息化高质量发展取得积极成效。 看主要指标，经济运行稳中提质。工业经济平稳运行，生产、效益同步增长。前三季度，行业增长面超过四分之三，10个工业大省平均增速约7%。 5月8日拍摄的天津博迈科海洋工程股份有限公…"
