    "content": "主要是一些测反应速度、记忆力和注意力的网页小游戏。 最开始真的就一个反应测试，做完觉得挺有意思，又忍不住做了几个。一个接着一个，现在竟然有 10 个了。 虽然不是什么新鲜的玩法，但毕竟是自己一点点折腾出来的，看着还是挺开心的。 最近又加了舒尔特方格，之前的反应测试也改了不少，现在能测五轮，还能看历史成绩。都不用注册，打开网页就能玩。 不过一直都是自己做、自己试，有些地方可能早就习惯了，反而发现不了问题。 所以还是想发出来给大家看看。如果有空愿意玩一玩，我就挺高兴了。哪里不好用也欢迎直接说，特别是手机端，我还想继续改…"
