    "author": "",
    "description": "中新网10月21日电 据“市说新语”微信公众号消息，近日，市场监管总局(国家标准委)批准发布《交通管理电子证照 机动车行驶证》(GB/T 48269—2026)国家标准，标准将自2027年4月1日起实施。此前，《交通管理电子证照 机动车驾驶证》已自2026年7月1日起实施。",
    "content": "中新网10月21日电 据“市说新语”微信公众号消息，近日，市场监管总局(国家标准委)批准发布《交通管理电子证照 机动车行驶证》(GB/T 48269—2026)国家标准，标准将自2027年4月1日起实施。此前，《交通管理电子证照 机动车驾驶证》已自2026年7月1日起实施。"
