    "content": "上海市医保局提醒，灵活就业人员应当坚持及时参保、连续缴费，避免断保。 据澎湃新闻报道，上海市制定的《关于灵活就业人员享受生育津贴待遇有关事项的通知》明确，自2027年5月1日起，灵活就业人员生育津贴与职工基本医疗保险待遇同步享受。对于通知落地前的过渡期，灵活就业人员享受的政策待遇，上海市医保局作出说明。 上海市医保局介绍，灵活就业人员参加该市职工基本医疗保险，待遇等待期为六个月，连续足额缴费满六个月且继续正常缴费的，自次月起享受职工医保待遇；待遇等待期内发生中断缴费的，待遇等待期重新计算。 在职职工、城乡居民停止享…"
