    "description": "美国总统特朗普20日说，现在讨论是否支持副总统万斯2028年参选总统“为时尚早”，并称两人此前未就此事进行过讨论。 特朗普当天在白宫椭圆形办公室回答记者提问时说，万斯“很有才干”，但“现在讨论此事还为时尚早，我们必须先度过中期选举”。 据美国媒体19日报道，万斯在接受采访时说，如果自己2028年参选美国总统，他认为特朗普会为其背书。不过，万斯同时承认，自己尚未与特朗普谈过此事。他还表示，特朗普也可能选择让共和党总统候选人“充分竞争”，而…",
    "content": "美国总统特朗普20日说，现在讨论是否支持副总统万斯2028年参选总统“为时尚早”，并称两人此前未就此事进行过讨论。 特朗普当天在白宫椭圆形办公室回答记者提问时说，万斯“很有才干”，但“现在讨论此事还为时尚早，我们必须先度过中期选举”。 据美国媒体19日报道，万斯在接受采访时说，如果自己2028年参选美国总统，他认为特朗普会为其背书。不过，万斯同时承认，自己尚未与特朗普谈过此事。他还表示，特朗普也可能选择让共和党总统候选人“充分竞争”，而不是提前确定支持人选。（记者、视频：王沛）"
